-- Thread 1 (sort 317): creation-ordinance-marriage-and-the-blessed-eunuch-in-jubilees-tobit-and-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'creation-ordinance-marriage-and-the-blessed-eunuch-in-jubilees-tobit-and-wisdom-of-solomon',
       'Creation-ordinance marriage and the blessed eunuch — Jubilees 3 + Tobit 8 + Wisdom of Solomon 3 on Matt 19:3-12',
       'Matt 19:3-12''s divorce-controversy + eunuchs-for-the-kingdom saying — the Pharisees-tempting on the Hillel-vs-Shammai-on-Deuteronomy-24:1-grounds-for-divorce trap; the King''s-appeal-behind-Mosheh (Moses)-to-Bereshit (Genesis) 1-2''s creation-ordinance with the FRAMEWORK-MAJOR *from the beginning it was not so* substance preserving the Torah-as-concession-to-hardness-of-heart architecture per Red Line #4; the *except-it-be-for-fornication* exception-clause preserving the substantial-sexual-impurity substance Deuteronomy 22:13-21 + Leviticus 20:10-21 already name; the eunuchs-for-the-kingdom saying recognizing voluntary-celibacy-in-kingdom-service as gift-substance some-receive — read against the wisdom-stream''s direct articulation of the same architectural-substance. Four moves: Jubilees 3:4 names the wisdom-stream''s direct articulation of the *it is not good that the man should be alone* substance from Bereshit (Genesis) 2:18 the King appeals behind Mosheh to at Matt 19:4; Jubilees 3:6 names the *bone of my bones and flesh of my flesh* one-flesh-from-the-beginning substance from Bereshit (Genesis) 2:23-24 the King restates at Matt 19:5 — the substance the framework reads per Red Line #11''s seed-and-marriage-covenant architecture in framework-deep''s *Paternal Seed and the Marriage-Covenant Absorption* section (the woman was-taken-from-the-man-himself); Tobit 8:6 names Tobias''s-prayer-at-the-marriage-bed directly invoking *You madest Adam, and gavest him Eve his wife... it is not good that man should be alone* — the wisdom-stream''s direct corroboration of the Father-joins-the-one-flesh-substance the King names at Matt 19:6''s *what therefore Elohim (God) hath joined together, let not man put asunder*; Wisdom of Solomon 3:14 names THE direct verbal-anchor for the blessed-eunuch-with-an-inheritance substance — *blessed is the eunuch, which with his hands has wrought no iniquity... for to him shall be given the special gift of faith, and an inheritance in the temple of Yahuah (the LORD) more acceptable to his mind* — the substance the Isaiah 56:3-5 promise carries-forward to the King''s eunuchs-for-the-kingdom-of-heaven''s-sake saying at Matt 19:12. The framework reads the cluster as the wisdom-stream''s direct corroboration of the architecture — the Father''s-will-from-the-beginning is the substance-of-reference for the marriage-substance; the eunuch-with-an-inheritance is the substance the voluntary-celibate-for-the-kingdom walks. The framework rules out: the Roman-Catholic-no-divorce-no-remarriage-absolute reading (the *porneia* exception-clause stands); the Roman-Catholic-mandatory-clerical-celibacy substance (the celibate-substance is gift, not mandate); the Reformation-marriage-mandate-with-no-honored-celibate-substance over-correction (the substance the King-himself walked and Sha''ul (Paul) walked is honored, not deficient).',
       sv.verse_id, ev.verse_id, 'complete_study', 317
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 19 AND sv.verse_number = 3
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 19 AND ev.verse_number = 12
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 318): receiving-the-children-and-parental-instruction-in-sirach-and-tobit
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'receiving-the-children-and-parental-instruction-in-sirach-and-tobit',
       'Receiving the children and parental instruction — Sirach (Ecclesiasticus) 7 + 3 + Tobit 4 on Matt 19:13-15',
       'Matt 19:13-15''s little-children-brought-to-the-King + the disciples''-rebuke-rebuked + *suffer little children, and forbid them not, to come unto me: for of such is the kingdom of heaven* — the practical-substance restatement of Matt 18:1-5''s child-substance — read against the wisdom-stream''s direct articulation of the children-and-parental-instruction architecture. Three moves: Sirach (Ecclesiasticus) 7:23 names the wisdom-stream''s direct articulation of the parental-instruction-of-children substance (*have you children? instruct them, and bow down their neck from their youth*) — the substance the parents-bringing-the-little-children-to-the-King enact at the practical-substance level, in continuity with Devarim (Deuteronomy) 6:6-7''s *thou shalt teach them diligently unto thy children* and Tehillim (Psalm) 78:5-7''s teaching-the-children substance; Sirach 3:1 names the children-hearing-the-father substance (*hear me your father, O children, and do thereafter, that you may be safe*) — the kingdom-citizens'' child-substance-disposition the King names at Matt 19:14 (the four-fold-child-substance the King had unpacked at Matt 18:1-5: humility, receptiveness, dependence, honesty), in continuity with the cause-and-effect-of-hearing per Red Line #11 (the kingdom-citizens'' child-substance is the substance-that-hears the Father''s-substance when the Father''s-substance speaks); Tobit 4:3 names the paternal-instruction-substance (*despise not your mother, but honour her all the days of your life*) — the broader-Tobit-4-context of the father-instructing-the-son in covenant-walking-substance, framing the Tanakh-paternal-blessing the King-enacts at Matt 19:15''s laying-on-of-hands (in continuity with Bereshit (Genesis) 48''s Ya''aqov (Jacob)-blessing-the-sons-of-Yoseph (Joseph) + Numbers 6:24-26''s priestly-blessing). The framework reads the cluster as the wisdom-stream''s direct corroboration of the architecture — children-as-the-recipients-of-covenant-transmission, the parents-bringing-the-children-to-the-Father-for-instruction-and-blessing, the kingdom-citizens'' child-substance-disposition. The framework rules out the inherited-Christian-original-innocence-by-default reading the institutional-tradition has built — the substance the King names is the disposition-substance the four-fold-child-substance carries, the substance-that-hears.',
       sv.verse_id, ev.verse_id, 'complete_study', 318
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 19 AND sv.verse_number = 13
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 19 AND ev.verse_number = 15
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 319): keep-the-commandments-as-life-and-lay-up-treasure-in-heaven-in-sirach-tobit-and-testaments-of-levi
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'keep-the-commandments-as-life-and-lay-up-treasure-in-heaven-in-sirach-tobit-and-testaments-of-levi',
       'Keep the commandments as life and lay up treasure in heaven — Sirach 17, 29, 3 + Tobit 4 + Testaments of Levi 7 on Matt 19:16-22 (FRAMEWORK-MAJOR)',
       'Matt 19:16-22''s rich-young-ruler — the young-man''s *what good thing shall I do, that I may have eternal life?* + the King''s *why callest thou me good? there is none good but one, that is, Elohim (God)* probe + the FRAMEWORK-MAJOR-LOADING moment at v.17''s *if thou wilt enter into life, keep the commandments* (DIRECT load-bearing scripture-anchor against Red Line #2''s antinomian-Paul reading) + the King''s-selection of five-of-the-Ten plus Vayikra (Leviticus) 19:18 + the young-man''s *all these things have I kept from my youth up* letter-keeping claim + the heart-Torah-diagnostic-test at v.21''s *if thou wilt be perfect, go and sell that thou hast, and give to the poor, and thou shalt have treasure in heaven* + the young-man''s departure-sorrowful — read against the wisdom-stream''s direct articulation of the keep-the-commandments-as-life + lay-up-treasure-in-heaven architecture. Six moves: Sirach (Ecclesiasticus) 17:11 names THE wisdom-stream verbal-anchor for the law-of-life-as-heritage substance (*he gave them knowledge, and the law of life for an heritage*) the King at Matt 19:17 stands on — in continuity with the Tanakh-substance of Devarim (Deuteronomy) 30:15-20''s *choose life... keep his commandments* and Vayikra (Leviticus) 18:5''s *which if a man do, he shall live in them*; Sirach 29:1 names the integrated-substance of mercy-to-the-neighbor AND commandment-keeping (*he that is merciful will lend to his neighbour; and he that strengtheneth his hand keepeth the commandments*) — the architecture the King''s-test integrates at the substance-of-the-rich-young-ruler''s love-of-neighbor-stopped-at-his-own-possessions; Sirach 3:8 names the fifth-commandment-substance (*honour your father and mother both in word and deed, that a blessing may come upon you from them*) at v.19''s King''s-selection of five-of-the-Ten; Sirach 29:11 names THE direct verbal-anchor for the lay-up-treasure-according-to-the-commandments substance (*lay up your treasure according to the commandments of the Most High, and it shall bring you more profit than gold*) the King restates at Matt 19:21''s *thou shalt have treasure in heaven*; Tobit 4:9 names the laying-up-good-treasure-against-the-day substance (*you layest up a good treasure for thyself against the day of necessity*) in the broader-Tobit-4:7-11 almsgiving-context (*give alms of your substance*); Testaments XII Levi 7 (chapter 18) verse 5 names THE most-direct verbal-anchor (*work righteousness, therefore, my children, upon the earth, that ye may have it as a treasure in heaven*) — the exact phrase the King restates at v.21. The framework reads the cluster as FRAMEWORK-MAJOR for Red Line #2 — the Tanakh, the wisdom-stream, the King''s-own-mouth, and the apostolic-restatement (1 Yochanan (John) 2:3-4''s 1234 of Truth, Revelation 14:12, 22:14) all hold the same architecture: commandment-keeping-as-life + righteousness-walked-on-the-earth-translating-into-treasure-in-heaven are one motion of one obedience. The framework rules out the inherited-Christian-substance-misreadings: NOT the antinomian-Paul collapse that-treats-commandment-keeping as the substance the cross-supposedly-abolished (the apostle Sha''ul (Paul) himself was Torah-observant per Acts 21:23-26); NOT the universal-poverty-mandate the v.21 substance does not require (the substance is heart-Torah-diagnostic per the young-man''s-specific-obstacle, NOT Marxist-redistribution); NOT the substance that-separates mercy-to-the-neighbor from commandment-keeping (the wisdom-stream-substance and the King''s-substance integrate the substances).',
       sv.verse_id, ev.verse_id, 'complete_study', 319
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 19 AND sv.verse_number = 16
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 19 AND ev.verse_number = 22
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 320): woes-on-the-rich-and-riches-cannot-save-in-1-enoch
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'woes-on-the-rich-and-riches-cannot-save-in-1-enoch',
       'Woes on the rich and riches cannot save — 1 Enoch 94-100 on Matt 19:23-26',
       'Matt 19:23-26''s camel-through-the-eye-of-a-needle hyperbole + the disciples'' *who then can be saved?* + the King''s *with men this is impossible; but with Elohim (God) all things are possible* — the substance the rich-young-ruler at vv.16-22 has-just-illustrated extended to the substance the kingdom-citizens''-substance carries-with-them as-the-substantial-warning — read against the Enochic wisdom-stream''s extended-corpus-of-woes-against-trust-in-wealth and the *riches shall not be able to save them* substance. Five moves: 1 Enoch 94:3 names THE direct Enochic verbal-anchor for the woe-against-trust-in-riches substance (*woe to you who are rich! For you have trusted in your riches, And from your riches shall you depart, Because you have not remembered Yahuah (God) of Spirits in the days of your riches*) — the same substance the King names at Matt 19:23''s *a rich man shall hardly enter into the kingdom of heaven*; 1 Enoch 97:7 names the rich-man''s-self-congratulation substance (*we have become rich with riches and have possessions; And we have acquired everything that we have desired*) — the architecture the rich-young-ruler-substance carried-out at his departure-sorrowful; 1 Enoch 94:8 names the rich-man''s-internal-monologue substance (*let us do what we purposed: For we have gathered silver, And many are the husbandmen in our houses*) — the substance the rich-fool parable at Luke 12:16-21 will-name explicitly (*I will pull down my barns, and build greater*); 1 Enoch 98:10 names the *ye know no ransom* substance — the architecture the disciples'' *who then can be saved?* at Matt 19:25 presupposes-the-failure-of (the inherited-substance that-had-associated-material-prosperity-with-the-Father''s-blessing collapses against the Enochic and the King''s warning); 1 Enoch 100:6 names THE direct verbal-anchor for the *riches shall not be able to save them* substance — the substance the King''s-statement at Matt 19:26''s *with men this is impossible; but with Elohim (God) all things are possible* lands. The framework reads the cluster as the Enochic wisdom-stream''s direct corroboration of the King''s-warning. The framework rules out: the Needle''s-Eye-gate explanation (no historical-evidence at any period); the prosperity-gospel-collapse-of-Tanakh-substance (Avraham (Abraham)''s-wealth and Yitschaq (Isaac)''s-hundredfold and the Deuteronomy 28-blessings stand in the Tanakh-context where the heart-was-with-Yahuah, NOT as universal-equation of riches-equals-blessing); the universalist-reading the v.26 substance does NOT support (the substance is the Father-able-to-soften-the-heart-the-possessions-hold per Yechezk''el (Ezekiel) 36:26-27''s new-heart substance + Yirmeyahu (Jeremiah) 31:33''s heart-Torah substance, NOT determinist-saving-of-all-rich-men-regardless-of-disposition). Grace is the door-home, the means-of-return-to-the-Father''s-Way, NOT the cancellation-of-the-substance-the-Father-commands per the *Grace, the Way, the New Heart, and the Mercy of Depart* section of framework-deep.md.',
       sv.verse_id, ev.verse_id, 'complete_study', 320
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 19 AND sv.verse_number = 23
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 19 AND ev.verse_number = 26
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 321): the-gathering-of-the-twelve-tribes-and-the-thrones-of-judgment-in-jubilees-sirach-wisdom-and-testaments-xii
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-gathering-of-the-twelve-tribes-and-the-thrones-of-judgment-in-jubilees-sirach-wisdom-and-testaments-xii',
       'The gathering of the twelve tribes and the thrones of judgment — Jubilees 1, 31 + Sirach 36 + Wisdom of Solomon 3 + Testaments XII Joseph 15 on Matt 19:27-30 (FRAMEWORK-MAJOR)',
       'Matt 19:27-30''s FRAMEWORK-MAJOR moment — Kefa (Peter)''s *we have forsaken all, and followed thee; what shall we have therefore?* + the King''s-mouth-most-direct-statement of the consummated-kingdom-architecture *in the regeneration when the Son of Adam shall sit in the throne of his glory, ye also shall sit upon twelve thrones, judging the twelve tribes of Yashar''el (Israel)* + the hundredfold-and-everlasting-life substance + the *many that are first shall be last* bridge to Matt 20 — read against the wisdom-stream''s direct articulation of the gathering-of-the-twelve-tribes + the thrones-of-judgment architecture. Five moves: Jubilees 1:15 names THE direct wisdom-stream verbal-anchor for the gathering-from-amongst-all-the-nations substance (*I shall gather them from amongst all the nations*) — the substance the King''s-Matt-19:28-statement presupposes-as-the-completed-gathering-architecture, in continuity with Yechezk''el (Ezekiel) 37:21-22''s two-sticks-becoming-one + Yeshayahu (Isaiah) 11:11-12''s *outcasts of Yashar''el (Israel)... dispersed of Yahudah (Judah) from the four corners of the earth* + Yirmeyahu (Jeremiah) 31:31''s new-covenant-with-both-houses; Jubilees 31:15 names the princes-and-judges-of-all-the-seed-of-the-sons-of-Jacob substance (*they will be princes and judges, and chiefs of all the seed of the sons of Jacob; They will speak the word of Yahuah (God) in righteousness, And they will judge all His judgments in righteousness*) — the substance the King''s *judging the twelve tribes of Yashar''el (Israel)* at v.28 carries-forward; Sirach (Ecclesiasticus) 36:11 names THE direct verbal-anchor for the gather-all-the-tribes-of-Jacob-together substance (*gather all the tribes of Jacob together, and inherit you them, as from the beginning*) — the wisdom-stream''s prayer-for-the-redemption-and-gathering-of-Yashar''el (Israel) the King at Matt 19:28 names as-completed-in-the-regeneration; Wisdom of Solomon 3:8 names the souls-of-the-righteous *they shall judge the nations, and have dominion over the people, and their Elohim (God) shall reign for ever* substance — the consummated-kingdom''s kingdom-of-priests architecture for the nations-left-alive-after-the-day-of-Yahuah (the LORD) per Shemot (Exodus) 19:6, Yeshayahu (Isaiah) 61:6, Revelation 1:6, 5:10; Testaments XII Joseph 15 (chapter 86) verse 2 names the twelve-harts-feeding-then-dispersed substance (*there were twelve harts feeding: and the nine were (first) dispersed over all the earth, and likewise also the three*) — the twelve-tribes-dispersed-and-gathered architecture the Tanakh-prophets had named (Yechezk''el (Ezekiel) 37:15-22''s two-sticks substance: nine = the ten-northern-tribes; three = the southern-house-substance + Levi-priestly-substance) and the King''s-substance restates at the King''s-mouth. The framework reads the cluster as FRAMEWORK-MAJOR for Red Line #11 — the twelve-tribes of Yashar''el (Israel) at the regeneration are LITERAL twelve-tribes, the paternal-blood remnant the Father-promised-through-the-prophets-and-the-wisdom-stream-and-now-states-at-the-King''s-mouth. The framework rules out: the institutional-Christian replacement-theology substance that-collapses-the-twelve-tribes into the church-as-spiritual-Yashar''el (Israel); the Hebrew-Roots-false-inclusion-gospel that-collapses-the-twelve-tribes into anyone-who-believes-and-Torah-keeps-is-therefore-Yashar''el (Israel) (both branches on the olive-tree are Yashar''el (Israel) — natural-branches the covenant-lineage of the patriarchs and-the-faithful-of-every-generation, wild-olive-branches the descendants-of-the-broken-off coming-home through-the-journey-the-prophets-named); the spiritualization-of-the-twelve-thrones into a-metaphor-of-spiritual-authority (the substance is concrete — twelve thrones in the consummated-kingdom for the twelve-apostles, in continuity with Revelation 4:4''s twenty-four-elders-around-the-throne and Revelation 21:12-14''s twelve-gates-named-for-the-twelve-tribes-with-twelve-foundations-named-for-the-twelve-apostles-of-the-Lamb).',
       sv.verse_id, ev.verse_id, 'complete_study', 321
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 19 AND sv.verse_number = 27
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 19 AND ev.verse_number = 30
ON CONFLICT (slug) DO NOTHING;

