-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s155_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 19
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'creation-ordinance-marriage-and-the-blessed-eunuch-in-jubilees-tobit-and-wisdom-of-solomon',
     'receiving-the-children-and-parental-instruction-in-sirach-and-tobit',
     'keep-the-commandments-as-life-and-lay-up-treasure-in-heaven-in-sirach-tobit-and-testaments-of-levi',
     'woes-on-the-rich-and-riches-cannot-save-in-1-enoch',
     'the-gathering-of-the-twelve-tribes-and-the-thrones-of-judgment-in-jubilees-sirach-wisdom-and-testaments-xii'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'creation-ordinance-marriage-and-the-blessed-eunuch-in-jubilees-tobit-and-wisdom-of-solomon',
     'receiving-the-children-and-parental-instruction-in-sirach-and-tobit',
     'keep-the-commandments-as-life-and-lay-up-treasure-in-heaven-in-sirach-tobit-and-testaments-of-levi',
     'woes-on-the-rich-and-riches-cannot-save-in-1-enoch',
     'the-gathering-of-the-twelve-tribes-and-the-thrones-of-judgment-in-jubilees-sirach-wisdom-and-testaments-xii'
   );

  RAISE NOTICE 'S155 Matt 19 verify: extras xrefs from canon/matthew/19 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 22 THEN
    RAISE EXCEPTION 'Expected at least 22 Matt-19 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 22 THEN
    RAISE EXCEPTION 'Expected at least 22 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
